pages.css:
@font-face {
  font-family: Nunito;
  font-style: normal;
  font-weight: 200 1000;
  font-display: swap;
  src: url(/site-assets/bb55a5ca5c2042335b39.ttf) format("truetype");
}

:root {
  --navy-accent: #031925;
  --ink: #000000;
  --paper: #ffffff;
  --blue-tint: #f7f9ff;
  --muted: var(--ink);
  --line: #cad6fa;
  --white: #fff;
  --font-body: Nunito, Arial, sans-serif;
  --font-display: Nunito, Arial, sans-serif;
  --gutter: clamp(24px, 6.5vw, 104px);
  --section-space: clamp(64px, 7vw, 96px);
  --scroll-thumb: #91a9ef;
  --scroll-track: #f7f9ff;
  --scroll-hover: #031925;
  --scroll-active: #123a4a;
}
* {
  box-sizing: border-box;
  scrollbar-color: var(--scroll-thumb) var(--scroll-track);
  scrollbar-width: auto;
}
*::-webkit-scrollbar {
  width: 12px;
  height: 12px;
}
*::-webkit-scrollbar-track {
  background: var(--scroll-track);
}
*::-webkit-scrollbar-thumb {
  background: var(--scroll-thumb);
  border: 3px solid var(--scroll-track);
  border-radius: 8px;
}
*::-webkit-scrollbar-thumb:hover {
  background: var(--scroll-hover);
}
*::-webkit-scrollbar-thumb:active {
  background: var(--scroll-active);
}
html {
  scroll-behavior: smooth;
  scroll-padding-top: 105px;
  scrollbar-gutter: stable;
}
body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font: 400 16px/1.55 var(--font-body);
  letter-spacing: -0.01em;
}
button,
input,
textarea {
  font: inherit;
  letter-spacing: inherit;
  caret-color: var(--navy-accent);
}
button,
a,
summary {
  -webkit-tap-highlight-color: transparent;
}
button,
summary {
  cursor: pointer;
}
button {
  color: inherit;
}
button:disabled {
  opacity: 0.45;
  cursor: default;
}
a {
  color: inherit;
  text-decoration: none;
  cursor: pointer;
  text-underline-offset: 5px;
}
a:hover {
  text-decoration: underline;
}
:is(a, button, summary, textarea, [tabindex]):focus-visible {
  outline: 3px solid #031925;
  outline-offset: 5px;
}
button:active,
.button:active {
  transform: translateY(1px);
}
::selection {
  background: var(--navy-accent);
  color: var(--paper);
}
h1,
h2,
h3,
p {
  margin: 0;
}
h1,
h2,
h3 {
  font-weight: 600;
  line-height: 1.15;
  text-wrap: balance;
  color: var(--navy-accent);
}
h1 {
  font-family: var(--font-display);
}
h2 {
  font-size: 36px;
  letter-spacing: -0.025em;
}
h3 {
  font-size: 23px;
  letter-spacing: -0.02em;
}
svg {
  display: block;
}
[hidden] {
  display: none !important;
}
.icon {
  width: 23px;
  height: 23px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex-shrink: 0;
}
.icon-library {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
}
.skip-link {
  position: fixed;
  top: 10px;
  left: 10px;
  z-index: 100;
  transform: translateY(-180%);
  padding: 12px 18px;
  background: var(--paper);
  color: var(--ink);
}
.skip-link:focus {
  transform: none;
}
.wrap {
  max-width: 1600px;
  padding-inline: var(--gutter);
  margin-inline: auto;
}
.content-wrap {
  width: min(100% - 2 * var(--gutter), 1120px);
  margin-inline: auto;
}
.white-section {
  background: var(--paper);
  color: var(--ink);
}
.eyebrow {
  font-size: 13px;
  font-weight: 600;
  line-height: 1.4;
  letter-spacing: -0.02em;
}
.accent {
  color: var(--ink);
}
.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 15px;
  min-height: 49px;
  padding: 12px 24px;
  border: 1px solid transparent;
  border-radius: 12px;
  font-size: 15px;
  font-weight: 600;
  line-height: 1.4;
  transition:
    background 0.2s,
    transform 0.2s;
  text-align: center;
}
.button:hover {
  text-decoration: none;
}
.button-white {
  background: var(--paper);
  color: var(--ink);
  border-color: var(--ink);
}
.button-white:hover {
  background: var(--blue-tint);
}
.button-primary {
  background: var(--paper);
  color: var(--ink);
  border-color: var(--ink);
}
.button-primary:hover {
  background: var(--blue-tint);
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 30;
  background: var(--navy-accent);
  color: var(--paper);
}
.nav-wrap {
  max-width: 1600px;
  min-height: 88px;
  padding-inline: var(--gutter);
  display: flex;
  align-items: center;
  gap: 38px;
  margin-inline: auto;
}
.brand {
  display: block;
  flex-shrink: 0;
  width: 169px;
}
.brand img {
  display: block;
  width: 100%;
  height: auto;
  filter: grayscale(1) brightness(0);
  mix-blend-mode: multiply;
}
.brand-light img {
  filter: grayscale(1) brightness(0) invert(1);
  mix-blend-mode: screen;
}
.desktop-nav {
  display: flex;
  align-items: center;
  gap: 25px;
  font-size: 15px;
}
.nav-dropdown {
  position: relative;
}
.nav-dropdown summary {
  list-style: none;
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 44px;
}
summary::-webkit-details-marker {
  display: none;
}
.nav-dropdown summary:hover,
.desktop-nav > a:hover {
  color: var(--blue-tint);
  text-decoration: none;
}
.nav-menu {
  position: absolute;
  left: -20px;
  top: 50px;
  width: 360px;
  padding: 15px;
  background: #031925;
  border: 1px solid #91a9ef;
  border-radius: 12px;
  box-shadow: 0 14px 25px #0003;
}
.nav-menu a {
  display: block;
  padding: 12px;
  border-radius: 7px;
  line-height: 1.4;
}
.nav-menu a:hover {
  background: #123a4a;
  text-decoration: none;
}
.nav-actions {
  display: flex;
  gap: 12px;
  margin-left: auto;
  align-items: center;
}
.nav-contact {
  border: 1px solid #cad6fa;
  border-radius: 12px;
  padding: 9px 21px;
  font-size: 15px;
  line-height: 1.4;
}
.nav-contact:hover {
  background: #123a4a;
  text-decoration: none;
}
.nav-actions .button {
  min-height: 40px;
  padding: 8px 23px;
}
.menu-toggle {
  display: none;
}
.mobile-nav {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  padding: 15px 24px 25px;
  background: var(--navy-accent);
  border-top: 1px solid #cad6fa;
}
.mobile-nav a {
  display: block;
  padding: 14px 0;
}

.hero-product {
  padding-bottom: var(--section-space);
}
.showcase-tabs {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
.showcase-tab {
  position: relative;
  border: 1px solid #cad6fa;
  background: var(--paper);
  color: var(--ink);
  border-radius: 17px;
  padding: 23px;
  display: flex;
  flex-direction: column;
  text-align: left;
  min-height: 194px;
}
.showcase-tab:hover {
  background: #f7f9ff;
}
.showcase-tab[aria-selected="true"] {
  border-color: #031925;
  background: var(--blue-tint);
}
.tab-eyebrow {
  font-size: 13px;
  margin-bottom: 14px;
}
.tab-title {
  color: var(--navy-accent);
  display: block;
  font-size: 24px;
  font-weight: 600;
  line-height: 1.2;
  margin-bottom: 11px;
}
.tab-description {
  font-size: 15px;
  line-height: 1.65;
}
.tab-line {
  height: 3px;
  width: 100%;
  display: block;
  background: #cad6fa;
  margin-top: auto;
  translate: 0 10px;
  opacity: 0;
}
.showcase-tab[aria-selected="true"] .tab-line {
  opacity: 1;
  background: var(--navy-accent);
}
.showcase-stage {
  margin-top: 30px;
}
.showcase-panel {
  height: min(46vw, 600px);
  min-height: 520px;
  border-radius: 24px;
  position: relative;
  overflow: hidden;
  isolation: isolate;
}
.analyse-panel {
  background:
    radial-gradient(ellipse at 76% 65%, #ffffff 0, transparent 60%),
    linear-gradient(115deg, #e4f1f8, #cce9f1 48%, #eaf3fc);
}
.analyse-panel:before {
  content: "";
  position: absolute;
  width: 150%;
  height: 60%;
  background: #fff4;
  filter: blur(32px);
  transform: rotate(-30deg);
  left: -20%;
  top: 15%;
  z-index: -1;
}
.demo-question {
  position: absolute;
  top: 9%;
  left: 25%;
  width: 52%;
  min-height: 0;
  background: #ffffff;
  color: var(--ink);
  border: 1px solid #fff;
  border-radius: 13px;
  box-shadow: -25px 35px 60px #03192518;
  transform: perspective(1400px) rotateY(-13deg) rotateX(5deg) rotate(-4deg);
  padding: 28px 34px;
}
.demo-wordmark {
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.03em;
}
.demo-wordmark > span {
  display: block;
  font-size: 7px;
  letter-spacing: 0.28em;
}
.demo-question-body {
  position: relative;
  padding: 30px 5px 0 34px;
}
.demo-step {
  position: absolute;
  left: 0;
  top: 32px;
  font-size: 12px;
}
.demo-question h2 {
  font-size: clamp(21px, 2.3vw, 31px);
  line-height: 1.17;
}
.demo-choices {
  display: grid;
  gap: 7px;
  margin-top: 22px;
  max-width: 360px;
}
.demo-choices a {
  min-height: 44px;
  padding: 8px;
  display: flex;
  align-items: center;
  gap: 10px;
  border: 1px solid #a8bdef;
  background: #f7f9ff;
  border-radius: 4px;
  font-size: 13px;
}
.demo-choices a:hover {
  background: var(--blue-tint);
  text-decoration: none;
  border-color: var(--navy-accent);
}
.keycap {
  width: 22px;
  height: 23px;
  flex-shrink: 0;
  border: 1px solid currentColor;
  border-radius: 3px;
  display: inline-grid;
  place-items: center;
  font-size: 11px;
}
.demo-hint {
  display: block;
  font-size: 10px;
  margin-top: 17px;
  color: var(--muted);
}
.orbital-label {
  position: absolute;
  z-index: 2;
  background: var(--paper);
  color: var(--ink);
  border: 1px solid #fff9;
  border-radius: 12px;
  backdrop-filter: blur(12px);
  box-shadow: 0 10px 35px #0319251c;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 18px;
  font-size: 16px;
}
.label-evidence {
  top: 14%;
  left: 8%;
  transform: rotate(-6deg);
}
.label-clarity {
  right: 7%;
  bottom: 22%;
  transform: rotate(5deg);
}
.small-spark {
  width: 23px;
  height: 23px;
}
.demo-caption {
  position: absolute;
  bottom: 22px;
  left: 20px;
  right: 20px;
  text-align: center;
  font-size: 12px;
  color: var(--ink);
  width: fit-content;
  margin-inline: auto;
  padding: 6px 12px;
  border-radius: 100px;
  background: var(--paper);
}
.decide-panel {
  color: var(--ink);
  background: radial-gradient(
    ellipse at 100% 100%,
    #c8e8ed 0,
    #d9eef4 35%,
    #edf6fb 72%
  );
}
.workflow-art {
  position: absolute;
  inset: 5% 16% 12% 25%;
  display: flex;
  align-items: center;
  flex-direction: column;
  transform: perspective(1200px) rotateY(-12deg) rotate(-7deg);
}
.flow-node {
  display: flex;
  align-items: center;
  gap: 18px;
  min-width: 335px;
  padding: 20px;
  border: 1px solid #cad6fa;
  background: linear-gradient(135deg, #ffffff, #f7f9ff);
  border-radius: 22px;
  box-shadow: 0 12px 30px #03192514;
  font-size: 22px;
  backdrop-filter: blur(10px);
}
.flow-node small {
  display: block;
  font-size: 11px;
  margin-top: 8px;
  color: var(--ink);
  background: var(--blue-tint);
  padding: 3px 8px;
  width: fit-content;
  border-radius: 2px;
}
.node-icon {
  display: grid;
  place-items: center;
  width: 54px;
  height: 54px;
  font-size: 34px;
  color: var(--ink);
  background: var(--blue-tint);
  border-radius: 12px;
}
.node-icon .icon {
  width: 30px;
  height: 30px;
}
.workflow-art > i {
  height: 28px;
  border-left: 2px solid #cad6fa;
}
.demo-question > .demo-caption {
  top: calc(100% + 16px);
  bottom: auto;
  left: 50%;
  right: auto;
  transform: translateX(-50%);
  width: max-content;
  max-width: 100%;
}
.decide-panel .demo-caption {
  color: var(--ink);
}
.sustain-panel {
  background:
    radial-gradient(ellipse at 70% 80%, #dce6ff, transparent 63%),
    linear-gradient(110deg, #ffffff, #edf2ff);
}
.readiness-card {
  width: 47%;
  margin: 4% 0 0 12%;
  padding: 26px 30px;
  background: var(--paper);
  color: var(--ink);
  border: 1px solid #fff;
  border-radius: 14px;
  box-shadow: 0 15px 30px #03192512;
  transform: rotate(-5deg);
}
.mini-eyebrow {
  font-size: 9px;
  letter-spacing: 0.035em;
  margin-bottom: 15px;
}
.readiness-card h2 {
  font: 400 36px/1.08 var(--font-display);
}
.readiness-card ul {
  list-style: none;
  padding: 0;
  margin: 18px 0;
}
.readiness-card li {
  font-size: 13px;
  padding: 6px 0;
}
.readiness-card li span {
  margin-right: 10px;
  color: var(--ink);
}
.readiness-card .button {
  min-height: 40px;
  font-size: 12px;
  padding: 10px 15px;
}
.readiness-label {
  position: absolute;
  right: 10%;
  top: 31%;
  font: 400 clamp(40px, 5.2vw, 68px)/1 var(--font-display);
  color: var(--ink);
  transform: rotate(6deg);
}
.bridge {
  position: relative;
  overflow: hidden;
  text-align: center;
  padding: var(--section-space) 24px;
  background: var(--paper);
}
.bridge h2 {
  font: 400 clamp(42px, 4.7vw, 62px)/1.12 var(--font-display);
  letter-spacing: -0.04em;
}
.bridge h2 span {
  color: inherit;
}
.bridge > p:last-child {
  margin-top: 27px;
  font-size: 15px;
  color: var(--muted);
}
.method-path {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  padding: 0;
  gap: 0;
  list-style: none;
  margin: 40px 0 0;
}
.method-path li {
  font-size: 14px;
  display: flex;
  align-items: center;
}
.method-path li + li:before {
  content: "→";
  margin: 0 20px;
  color: var(--ink);
}
.feature-section {
  padding: var(--section-space) 0;
}
.feature-row {
  display: grid;
  grid-template-columns: 40% 56%;
  gap: 4%;
  align-items: center;
}
.feature-copy > .eyebrow {
  margin-bottom: 18px;
  font-size: 12px;
}
.feature-copy h2 {
  font-size: 36px;
}
.feature-copy > p:not(.eyebrow) {
  font-size: 19px;
  line-height: 1.55;
  max-width: 52ch;
  margin-top: 20px;
}
.feature-copy > .button {
  margin-top: 30px;
}
.feature-art {
  position: relative;
  height: 415px;
  border-radius: 22px;
  overflow: hidden;
  isolation: isolate;
}
.diagnostic-art {
  background:
    radial-gradient(ellipse at 90% 20%, #dce6ff, transparent 56%),
    linear-gradient(135deg, #f7f9ff, #edf2ff);
}
.evidence-board {
  width: 71%;
  position: absolute;
  left: 17%;
  top: 21%;
  padding: 21px;
  background: #ffffff;
  border-radius: 10px;
  transform: perspective(900px) rotateY(-18deg) rotate(7deg);
  box-shadow: 6px 15px 30px #03192512;
  color: var(--ink);
}
.board-top {
  font-size: 13px;
  font-weight: 600;
}
.board-top span {
  display: block;
  font-size: 7px;
  font-weight: 400;
  margin-top: 4px;
}
.evidence-board h3 {
  font: 400 28px/1.1 var(--font-display);
  margin-top: 20px;
}
.evidence-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 21px;
}
.evidence-grid > div {
  padding: 10px;
  border: 1px solid #cad6fa;
  border-radius: 4px;
  font-size: 11px;
}
.evidence-grid span {
  display: block;
  margin-bottom: 5px;
  font-size: 8px;
  color: var(--ink);
}
.evidence-board > p {
  font-size: 9px;
  margin-top: 17px;
}
.evidence-board b {
  float: right;
}
.floating-prompt {
  position: absolute;
  right: 6%;
  top: 10%;
  padding: 19px 15px;
  min-width: 205px;
  font-size: 12px;
  background: #ffffffed;
  border: 1px solid #ffffffad;
  backdrop-filter: blur(5px);
  border-radius: 12px;
  transform: rotate(9deg);
  z-index: 2;
}
.floating-prompt span {
  float: right;
  margin-left: 16px;
}
.benefits {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 48px;
}
.benefits article {
  position: relative;
  padding-left: 40px;
}
.benefit-icon {
  position: absolute;
  left: 0;
  top: 2px;
  width: 25px;
  height: 25px;
}
.benefits h3 {
  font-size: 21px;
  line-height: 1.25;
}
.benefits p {
  margin-top: 12px;
  font-size: 15px;
  line-height: 1.6;
}
.section-statement {
  text-align: center;
  padding: var(--section-space) 24px;
}
.section-statement h2 {
  font: 400 48px/1.1 var(--font-display);
  letter-spacing: -0.035em;
}
.decision-section {
  padding-bottom: var(--section-space);
}
.feature-row.reverse {
  grid-template-columns: 56% 40%;
}
.feature-row.reverse .feature-copy {
  order: 2;
}
.feature-row.reverse .feature-art {
  order: 1;
}
.white-section .feature-copy > .eyebrow {
  color: var(--ink);
}
.decision-art {
  background: radial-gradient(
    ellipse at 40% 100%,
    #c8e8ed 0,
    #e2f0f7 45%,
    #f2f8fc 85%
  );
}
.decision-map {
  display: flex;
  align-items: center;
  flex-direction: column;
  padding: 38px 15px;
  transform: rotate(-7deg);
}
.map-node {
  width: 80%;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 15px;
  border: 1px solid #cad6fa;
  border-radius: 16px;
  background: #ffffff;
  font-size: 17px;
  box-shadow: 0 6px 20px #03192512;
}
.map-node > span {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 8px;
  background: var(--blue-tint);
  color: var(--ink);
  font-size: 25px;
}
.map-node .icon {
  width: 24px;
  height: 24px;
}
.map-node small {
  display: block;
  font-size: 10px;
  margin-top: 4px;
}
.map-connector {
  height: 26px;
  border-left: 1px solid #8daebd;
}
.highlighted {
  background: #f7f9ff;
}
.transition-section {
  position: relative;
  padding-top: var(--section-space);
  overflow: hidden;
}
.transition-art {
  background:
    radial-gradient(ellipse at 85% 85%, #ffffff 0, transparent 59%),
    linear-gradient(125deg, #d7edf2, #edf5fb);
}
.handover-sheet {
  position: absolute;
  width: 68%;
  left: 13%;
  top: 12%;
  padding: 22px;
  background: #ffffff;
  color: var(--ink);
  transform: rotate(-8deg);
  border-radius: 10px;
  box-shadow: 0 10px 22px #0003;
}
.sheet-label {
  font-size: 8px;
}
.handover-sheet h3 {
  font: 400 37px/1.03 var(--font-display);
  margin: 20px 0;
}
.handover-sheet h3 em {
  color: inherit;
}
.handover-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid #cad6fa;
  padding: 10px 0;
  font-size: 11px;
}
.ready-badge {
  position: absolute;
  bottom: 14%;
  right: 6%;
  transform: rotate(9deg);
  padding: 19px;
  background: #ffffff;
  color: var(--ink);
  border-radius: 10px;
  font-size: 17px;
  line-height: 1.3;
  box-shadow: 0 5px 17px #0002;
}
.practice-section {
