:root {
  --navy: #031925;
  --cyan: #70d0e5;
}
.site-header {
  background: var(--navy);
  color: #d3e3e9;
}
.site-header .nav-wrap {
  min-height: 82px;
  padding-inline: clamp(24px, 6.5vw, 104px);
}
.site-header .brand {
  width: 163px;
}
.desktop-nav {
  margin-left: auto;
  gap: 28px;
}
.nav-actions {
  margin-left: auto;
}
.site-header .nav-contact {
  border: 0;
  padding: 10px 12px;
}
.site-header .nav-contact:hover {
  background: transparent;
  color: var(--cyan);
}
.site-header .nav-actions .button {
  color: #d7edf4;
  background: transparent;
  border: 1px solid #608a9b;
  border-radius: 100px;
}
.site-header .nav-actions .button:hover {
  background: #123a4a;
  border-color: var(--cyan);
}
.nav-menu,
.mobile-nav {
  background: #082532;
  border-color: #376173;
}
.nav-menu a:hover {
  background: #123a4a;
}
.nav-dropdown summary:hover,
.desktop-nav > a:hover,
.menu-toggle:hover {
  color: var(--cyan);
}
.wave-hero {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  color: #e4f0f5;
  background: var(--navy);
}
.wave-visual {
  position: absolute;
  z-index: -2;
  inset: -5% -2%;
  transform: translate3d(var(--wave-x, 0px), var(--wave-y, 0px), 0);
  transition: transform 1.1s cubic-bezier(0.15, 0.6, 0.3, 1);
  pointer-events: none;
}
.wave-visual img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: center 50%;
}
.wave-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background:
    linear-gradient(
      90deg,
      #031925 0%,
      #031925f5 26%,
      #03192566 43%,
      #03192500 70%
    ),
    linear-gradient(
      0deg,
      #031925bb,
      transparent 28%,
      transparent 88%,
      #031925a8
    );
}
#wave-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: -1;
}
.wave-content {
  min-height: clamp(550px, 44vw, 660px);
  padding: 58px clamp(24px, 6.5vw, 104px) 122px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}
.wave-copy {
  max-width: 740px;
  min-width: 0;
}
.wave-copy .eyebrow {
  font-size: 11px;
  letter-spacing: 0.16em;
  font-weight: 600;
  color: #b4ced9;
  margin-bottom: 26px;
}
.wave-copy h1 {
  font-family: var(--font-display);
  font-size: clamp(52px, 6.1vw, 88px);
  font-weight: 650;
  line-height: 1.04;
  letter-spacing: -0.035em;
  color: #f0f7fa;
}
.wave-copy h1 span {
  color: var(--cyan);
}
.wave-description {
  font-size: clamp(18px, 1.55vw, 21px);
  line-height: 1.55;
  letter-spacing: 0.005em;
  margin-top: 26px;
  color: #c5dae3;
}
.wave-actions {
  display: flex;
  gap: 12px;
  align-items: center;
  margin-top: 30px;
  flex-wrap: wrap;
}
.wave-actions .button {
  border-radius: 100px;
  min-height: 52px;
  font-size: 14px;
  padding: 12px 25px;
  gap: 14px;
}
.button-cyan {
  background: var(--cyan);
  color: #05212e;
}
.button-cyan:hover {
  background: #a0e6f3;
  transform: translateY(-2px);
}
.wave-actions .icon {
  width: 18px;
  height: 18px;
}
.button-wave-outline {
  background: #062332d9;
  border-color: #608494;
  color: #e0eff5;
}
.button-wave-outline:hover {
  border-color: #70c9e2;
  background: #103c4d;
}
.wave-manifesto {
  margin: 118px 0 0;
  padding: 8px 0 8px 22px;
  border-left: 1px solid #67abc5;
  font-size: 12px;
  font-weight: 600;
  line-height: 2;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: #d0e4ed;
  flex-shrink: 0;
  text-shadow: 0 1px 8px #031925;
}
.wave-footer {
  position: absolute;
  bottom: 24px;
  left: 0;
  right: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 16px 0 0;
  width: min(calc(100% - 2 * clamp(24px, 6.5vw, 104px)), 1392px);
  margin-inline: auto;
  border-top: 1px solid #60849466;
  pointer-events: none;
}
.wave-hint {
  color: #b4ced9;
  font-size: 13px;
  line-height: 1.5;
}
.wave-controls {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}
.wave-controls button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  padding: 9px 14px;
  border: 1px solid transparent;
  border-radius: 100px;
  background: #031925b3;
  color: #c5dae3;
  font-size: 13px;
  white-space: nowrap;
  pointer-events: auto;
  transition: color 160ms ease, background-color 160ms ease, border-color 160ms ease;
}
.wave-controls #wave-ripple {
  border-color: #608494;
  color: #e0eff5;
}
.wave-controls button:hover {
  color: #fff;
  background: #123a4a;
  border-color: var(--cyan);
}
.wave-controls button:disabled {
  cursor: default;
  color: #9bb9c7;
  border-color: transparent;
  background: transparent;
}
[data-wave-motion="off"] .wave-hint {
  visibility: hidden;
}
.wave-controls svg {
  width: 20px;
  height: 20px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
}
.wave-controls .wave-resume-icon {
  display: none;
}
[data-wave-motion="off"] .wave-pause-icon {
  display: none;
}
[data-wave-motion="off"] .wave-resume-icon {
  display: block;
}
[data-wave-motion="off"] .wave-visual {
  transition: none;
}
.wave-hero :is(a, button):focus-visible,
.site-header :is(a, button, summary):focus-visible {
  outline-color: var(--cyan);
}
.showcase {
  padding-top: 45px;
}
@media (max-width: 1050px) {
  .desktop-nav {
