.journey {
  width: 100vw;
  max-width: 100vw;
  height: 100dvh;
  max-height: none;
  inset: 0;
  margin: 0;
  padding: 0;
  border: 0;
  background: var(--paper);
  color: var(--ink);
  overflow: auto;
  scrollbar-gutter: stable;
}
.journey::backdrop {
  background: rgb(3 25 37 / 32%);
}
body.journey-open {
  overflow: hidden;
}
.journey-shell {
  min-height: 100%;
  display: flex;
  flex-direction: column;
}
.journey-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
  padding: 25px 45px;
  flex-shrink: 0;
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--paper);
}
.journey-top .brand {
  width: 178px;
}
.journey-name {
  font-size: 12px;
  color: var(--muted);
}
.close-journey {
  display: flex;
  align-items: center;
  gap: 13px;
  background: transparent;
  border: 0;
  padding: 8px;
  font-size: 12px;
  min-height: 44px;
}
.close-journey:hover {
  text-decoration: underline;
  text-underline-offset: 4px;
}
.progress-wrap {
  padding: 0 45px;
}
.journey-progress {
  height: 3px;
  background: #cad6fa;
  overflow: hidden;
  border-radius: 2px;
}
.journey-progress span {
  display: block;
  width: 100%;
  height: 100%;
  background: #031925;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.35s;
}
.journey-body {
  width: 100%;
  max-width: 840px;
  margin: auto;
  padding: 40px 65px 25px;
}
.step-heading {
  position: relative;
}
.step-heading > span {
  display: flex;
  align-items: center;
  gap: 6px;
  position: absolute;
  right: calc(100% + 15px);
  top: 8px;
  font-size: 13px;
}
.step-heading > span .icon {
  width: 18px;
  height: 18px;
}
.journey h2 {
  font:
    600 clamp(29px, 3vw, 38px)/1.25 Nunito,
    sans-serif;
  letter-spacing: -0.025em;
  max-width: 700px;
}
.journey h2:focus {
  outline: none;
}
.question-help {
  margin-top: 14px;
  font-size: 15px;
  color: var(--muted);
}
.answer-list {
  display: grid;
  gap: 8px;
  max-width: 630px;
  margin-top: 25px;
}
.answer-option {
  display: flex;
  align-items: center;
  text-align: left;
  gap: 12px;
  background: #ffffff;
  border: 1px solid #91a9ef;
  border-radius: 7px;
  padding: 11px 16px;
  min-height: 52px;
  font-size: 16px;
  line-height: 1.45;
  transition: background-color 0.16s;
}
.answer-option:hover {
  background: #f7f9ff;
}
.answer-option[aria-checked="true"] {
  background: #f7f9ff;
  border: 2px solid var(--navy-accent);
  padding: 10px 15px;
}
.answer-option .keycap {
  background: var(--paper);
  width: 25px;
  height: 26px;
}
.answer-option[aria-checked="true"] .keycap {
  background: var(--navy-accent);
  color: var(--paper);
}
.answer-option .choice-check {
  width: 20px;
  height: 20px;
  margin-left: auto;
  visibility: hidden;
}
.answer-option[aria-checked="true"] .choice-check {
  visibility: visible;
}
.question-actions {
  margin-top: 25px;
  display: flex;
  align-items: center;
  gap: 17px;
}
.question-actions .button {
  gap: 15px;
  padding: 12px 19px;
  min-height: 47px;
  font-size: 15px;
}
.keyboard-hint {
  font-size: 11px;
  color: var(--muted);
}
.keyboard-hint strong {
  color: var(--ink);
}
.answer-error {
  min-height: 25px;
  font-size: 12px;
  margin-top: 10px;
  color: var(--ink);
}
.answer-error:empty {
  display: none;
}
.journey-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
  padding: 20px 45px 8px;
  font-size: 11px;
}
.journey-bottom > div {
  display: flex;
  align-items: center;
  gap: 18px;
}
.text-button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 0;
  background: transparent;
  padding: 6px 0;
  min-height: 34px;
  font-size: 12px;
  text-decoration: underline;
  text-underline-offset: 4px;
  cursor: pointer;
}
.text-button:disabled {
  text-decoration: none;
}
.back-arrow {
  width: 18px;
  height: 18px;
  transform: rotate(180deg);
}
.journey-privacy {
  padding: 8px 45px 24px;
  text-align: center;
  color: var(--muted);
  font-size: 10px;
}
.result-intro {
  margin-bottom: 27px;
}
.result-check {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--blue-tint);
  margin-bottom: 22px;
}
.result-intro h2 {
  font-family: var(--font-display);
  font-size: 48px;
  line-height: 1.1;
}
.result-intro p {
  margin-top: 13px;
  font-size: 14px;
  color: var(--muted);
}
.result-recommendation {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 24px 0;
}
.result-recommendation h3 {
  font-size: 25px;
  font-weight: 600;
}
.result-recommendation p {
  margin-top: 12px;
  font-size: 14px;
}
.result-recommendation ul {
  margin: 17px 0 0;
  padding-left: 19px;
  font-size: 13px;
  line-height: 1.9;
}
.answer-summary {
  margin: 20px 0;
  font-size: 13px;
}
.answer-summary summary {
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-block: 8px;
}
.answer-summary summary span {
  color: var(--muted);
  font-size: 11px;
  text-decoration: underline;
  text-underline-offset: 4px;
}
.answer-summary dl {
  background: var(--blue-tint);
  padding: 20px;
  border-radius: 8px;
}
.answer-summary dt {
  font-size: 11px;
  color: var(--muted);
}
.answer-summary dd {
  margin: 5px 0 16px;
  font-size: 13px;
}
.answer-summary dd:last-child {
  margin-bottom: 0;
}
.context-label {
  display: block;
  font-size: 13px;
}
.context-label span {
  color: var(--muted);
  margin-left: 5px;
  font-size: 11px;
}
textarea {
  display: block;
  width: 100%;
  resize: vertical;
  min-height: 85px;
  max-height: 300px;
  margin-top: 10px;
  padding: 13px;
  background: transparent;
  border: 1px solid #91a9ef;
  border-radius: 7px;
  color: var(--ink);
  font-size: 13px;
  line-height: 1.6;
}
textarea::placeholder {
  color: var(--muted);
  opacity: 1;
}
.result-actions {
  display: flex;
  align-items: center;
  gap: 25px;
  margin-top: 23px;
}
.share-note,
.download-status {
  font-size: 11px;
  color: var(--muted);
  margin-top: 12px;
}
.download-status:empty {
  display: none;
}
.journey[data-result="true"] .journey-body {
  padding-top: 40px;
  padding-bottom: 30px;
}
@media (max-width: 760px) {
  .journey-top {
    padding: 18px 24px;
    gap: 14px;
  }
  .journey-top .brand {
    width: 151px;
  }
  .journey-name {
    display: none;
  }
  .progress-wrap {
    padding-inline: 24px;
  }
  .journey-body {
    padding: 42px 30px 24px 52px;
  }
  .journey h2 {
    font-size: 30px;
  }
  .step-heading > span {
    right: calc(100% + 8px);
    top: 6px;
    font-size: 11px;
    gap: 3px;
  }
  .step-heading > span .icon {
    width: 14px;
    height: 14px;
  }
  .question-help {
    font-size: 14px;
  }
  .answer-option {
    font-size: 14px;
  }
  .journey-bottom {
    padding-inline: 24px;
    gap: 12px;
  }
  .journey-bottom > div {
    gap: 8px;
  }
  .journey-privacy {
    padding-inline: 24px;
  }
  .journey[data-result="true"] .journey-body {
    padding: 32px 24px;
  }
  .result-intro h2 {
    font-size: 39px;
  }
  .result-recommendation h3 {
    font-size: 24px;
  }
  .result-actions {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }
  textarea {
    font-size: 16px;
  }
}
@media (max-width: 440px) {
  .close-journey > span {
    display: none;
  }
  .journey-body {
    padding: 36px 24px 20px 44px;
  }
  .journey h2 {
    font-size: 28px;
  }
  .question-help {
    font-size: 13px;
  }
  .answer-option {
    font-size: 13px;
    padding: 12px 11px;
    gap: 10px;
  }
  .answer-option[aria-checked="true"] {
    padding: 11px 10px;
  }
  .answer-option .keycap {
    width: 22px;
    height: 23px;
    font-size: 10px;
  }
  .answer-option .choice-check {
    width: 17px;
    height: 17px;
  }
  .keyboard-hint {
    display: none;
  }
  .journey-bottom {
    font-size: 10px;
    padding-top: 16px;
  }
  .journey-bottom .motion-control {
    display: none;
  }
  .journey-privacy {
    font-size: 10px;
    padding-bottom: 18px;
  }
  .result-recommendation p {
    font-size: 13px;
  }
}

:root {
  --surface-ice: #f0f8fb;
  --surface-blue: #f4f7fc;
  --surface-cyan: #eaf6f8;
}

/* Lower-page surfaces share the hero's cool palette. Text keeps its own tokens. */
.showcase {
  background: var(--surface-blue);
}
.showcase-tab {
  background: #f8fbff;
}
.showcase-tab[aria-selected="true"] {
  background: var(--paper);
}
.decision-section {
  background: var(--surface-blue);
}
.transition-section {
  background: var(--surface-ice);
}
.practice-section,
.embedded-section {
  background: var(--surface-cyan);
}
.embedded-quote {
  background: var(--paper);
}
.method-section {
  background: var(--surface-blue);
}
.contact {
  background: var(--surface-cyan);
  border-top: 0;
}
.benefits h3,
.method-tiles h3 {
  font-weight: 700;
}
.method-tiles h3 {
  font-size: 20px;
}

.connection-section {
  padding: var(--section-space) 0;
  background: var(--surface-ice);
  overflow: clip;
}
.connection-layout {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.2fr);
  grid-template-areas: "copy visual" "explorer visual";
  align-items: center;
  gap: 32px clamp(24px, 4vw, 64px);
}
.connection-copy {
  grid-area: copy;
}
.connection-explorer {
  grid-area: explorer;
}
.connection-label {
  font-size: 14px;
  margin-bottom: 20px;
}
.connection-copy > h2 {
  font-size: clamp(38px, 4.1vw, 58px);
  line-height: 1.08;
  letter-spacing: -0.035em;
}
.connection-intro {
  max-width: 36ch;
  margin-top: 24px;
  font-size: 18px;
}
.connection-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.connection-tabs button {
  min-height: 44px;
  padding: 10px 16px;
  border: 1px solid transparent;
  border-radius: 12px;
  color: var(--ink);
  background: transparent;
  font-size: 15px;
}
.connection-tabs button:hover {
  background: #ffffff80;
}
.connection-tabs button[aria-selected="true"] {
  background: var(--paper);
  border-color: var(--ink);
  font-weight: 700;
}
.connection-readout {
  display: grid;
  margin-top: 26px;
}
.connection-readout > [role="tabpanel"] {
  grid-area: 1 / 1;
}
/* Reserve the tallest answer, so choosing another thread never shifts the page. */
.connection-readout > [hidden] {
  display: block !important;
  visibility: hidden;
  pointer-events: none;
}
.connection-readout h3 {
  font-size: 24px;
  line-height: 1.25;
}
.connection-readout p {
  max-width: 40ch;
  margin-top: 12px;
  font-size: 16px;
}
.connection-readout a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  margin-top: 12px;
}
.connection-visual {
  grid-area: visual;
  min-width: 0;
  margin: 0;
  text-align: center;
}
.connection-sculpture {
  display: block;
  width: 100%;
  padding: 0;
  border: 0;
  border-radius: 22px;
  background: transparent;
  perspective: 1000px;
  mix-blend-mode: multiply;
}
.connection-sculpture img {
  display: block;
  width: 100%;
  height: auto;
  mask-image: linear-gradient(to right, transparent, #000 7%, #000 93%, transparent), linear-gradient(to bottom, transparent, #000 5%, #000 94%, transparent);
  mask-composite: intersect;
  transform: rotate(var(--thread-turn, -6deg)) scale(0.94);
  transition: transform 700ms cubic-bezier(0.2, 0.75, 0.2, 1);
}
.connection-visual[data-view="processes"] {
  --thread-turn: 7deg;
}
.connection-visual[data-view="decisions"] {
  --thread-turn: -17deg;
}
.connection-sculpture:hover img {
  transform: rotate(var(--thread-turn, -6deg)) scale(0.99);
}
.connection-sculpture:active img {
  transform: rotate(var(--thread-turn, -6deg)) scale(0.96);
}
.connection-visual figcaption {
  max-width: 36ch;
  margin: 20px auto 0;
  font-size: 13px;
}

@media (max-width: 760px) {
  .connection-layout {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas: "copy" "visual" "explorer";
    gap: 28px;
  }
  .connection-copy > h2 {
    font-size: clamp(36px, 8vw, 48px);
  }
  .connection-visual {
    max-width: 450px;
    width: 100%;
    margin: 0 auto;
  }
  .connection-tabs {
    gap: 4px;
  }
  .connection-tabs button {
    padding-inline: 12px;
    font-size: 14px;
  }
  .connection-intro {
    font-size: 17px;
  }
  .connection-readout h3 {
    font-size: 23px;
    font-weight: 700;
  }
  .connection-visual figcaption {
    margin-top: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .connection-sculpture img,
  .connection-sculpture:hover img,
  .connection-sculpture:active img {
    transition: none;
    transform: none;
  }
}
html[data-motion="off"] .connection-sculpture img,
html[data-motion="off"] .connection-sculpture:hover img,
html[data-motion="off"] .connection-sculpture:active img {
  transition: none;
  transform: none;
}

/* Alternating surfaces and interactive refinements. */
.showcase, #diagnostic, #transition, #embedded, #contact { background: #fff; }
#approach, #decisions, #about, .method-section { background: var(--surface-ice); }
.showcase-tab { transition: background-color 180ms ease, border-color 180ms ease, transform 180ms ease; }
.showcase-tab:hover, .showcase-tab:focus-visible { background: #dceff3; border-color: #6a98a8; transform: translateY(-5px); }
.showcase-tab:active { transform: translateY(-1px); }
.wave-manifesto { color: #fff; font-weight: 800; text-shadow: 0 2px 8px #031925; }
.wave-content { padding-bottom: 72px; }
.analyse-panel { height: auto; min-height: 590px; }
.analyse-panel .demo-question { position: relative; top: auto; left: auto; width: min(calc(100% - 96px), 740px); margin: 64px auto 80px; padding: 32px 40px; transform: rotate(-2deg); }
.demo-question h2 { max-width: 20ch; font-size: clamp(28px, 3vw, 38px); line-height: 1.2; text-wrap: balance; }
.demo-question-body { padding-top: 24px; }
.demo-choices { gap: 10px; }
.demo-choices a { padding: 12px 14px; min-height: 48px; font-size: 15px; line-height: 1.45; }
.demo-hint { display: block; font-size: 13px; line-height: 1.5; }
.embedded-quote { justify-content: flex-start; align-items: flex-start; }
.embedded-quote .quote-mark { display: block; height: 76px; line-height: 1; font-size: 100px; }
.embedded-quote h2 { margin-top: 12px; width: 100%; }
.decision-art { overflow: visible; height: auto; min-height: 530px; display: flex; align-items: center; padding: 28px; }
.decision-builder { width: 100%; padding: 28px; border-radius: 18px; background: #fff; color: #000; }
.decision-progress { font-size: 13px; margin-bottom: 20px; }
.decision-builder fieldset { border: 0; padding: 0; margin: 0; min-width: 0; }
.decision-builder legend, .decision-result h3 { font-size: 27px; font-weight: 700; line-height: 1.2; color: var(--navy-accent); margin-bottom: 24px; }
.decision-builder label { display: block; margin: 16px 0 8px; font-size: 15px; font-weight: 700; }
.decision-builder :is(input, textarea, select) { width: 100%; min-height: 48px; padding: 12px; font: inherit; font-size: 16px; color: #000; background: #f7fafc; border: 1px solid #91a9b4; border-radius: 8px; }
.decision-builder textarea { resize: vertical; }
.decision-builder :is(input, textarea)::placeholder { color: #52636c; }
.decision-builder fieldset > p, .decision-result > p { font-size: 14px; line-height: 1.5; margin-top: 12px; }
.decision-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 24px; }
.decision-actions .button { color: #fff; background: var(--navy-accent); border-color: var(--navy-accent); }
.decision-actions [data-decision-back], .decision-actions [data-decision-edit] { color: #031925; background: #fff; }
.decision-privacy { margin-top: 20px; font-size: 12px; line-height: 1.5; }
.decision-result dt { margin-top: 16px; font-size: 13px; font-weight: 700; }
.decision-result dd { margin: 4px 0 0; line-height: 1.5; overflow-wrap: anywhere; }
@media (max-width: 760px) {
  .wave-content { min-height: 640px; padding-bottom: 260px; }
  .wave-manifesto { bottom: 32px; }
  .analyse-panel { min-height: 0; }
  .analyse-panel .demo-question { width: calc(100% - 32px); margin: 64px 16px 80px; padding: 24px 20px; transform: none; }
  .demo-question h2 { font-size: clamp(25px, 6.5vw, 32px); max-width: 20ch; text-wrap: wrap; }
  .demo-question-body { padding-top: 22px; }
  .demo-step { display: none; }
  .decision-art { padding: 16px; min-height: 0; }
  .decision-builder { padding: 24px 18px; }
  .decision-builder legend { font-size: 25px; }
  .embedded-quote { min-height: 0; }
}
@media (prefers-reduced-motion: reduce) {
  .showcase-tab:hover, .showcase-tab:focus-visible { transform: none; }
  .showcase-tab { transition: none; }
}
html[data-motion="off"] .showcase-tab { transform: none; transition: none; }

.method-step {
  display: block;
  min-width: 0;
  border-radius: 16px;
}
.method-step:hover {
  text-decoration: none;
}
.method-step:hover h3 {
  text-decoration: underline;
  text-underline-offset: 5px;
}
.method-glyph {
  display: grid;
  place-items: center;
  width: 84px;
  height: 84px;
  margin: 0 auto 20px;
  border: 1px solid var(--line);
  border-radius: 22px;
  background: var(--paper);
  color: var(--ink);
}
.method-icon {
  display: block;
  width: 38px;
  height: 38px;
  overflow: visible;
}
.method-tiles p {
  font-size: 14px;
  line-height: 1.4;
}

/* GSAP owns transforms on these controls while motion is enabled. */
.has-gsap-micro :is(header, main) .button {
  transition-property: background-color, border-color, color, box-shadow;
}
.has-gsap-micro :is(header, main) .button:is(:hover, :active) {
  transform: none;
}

@media (max-width: 760px) {
  .method-step {
    display: grid;
    grid-template-columns: 60px minmax(0, 1fr);
    align-items: center;
    gap: 4px 18px;
    text-align: left;
  }
  .method-glyph {
    grid-row: span 2;
    width: 60px;
    height: 60px;
    margin: 0;
    border-radius: 16px;
  }
  .method-icon {
    width: 32px;
    height: 32px;
  }
  .method-step p {
    align-self: start;
  }
}

@media (prefers-reduced-motion: reduce) {
  .button:is(:hover, :active) {
    transform: none;
  }
}
html[data-motion="off"] .button:is(:hover, :active) {
  transform: none;
}
